_LIMIT_RE = re.compile(r"[1-9][0-9]*")
_READ_CHUNK = 65536


def _limit_value(token):
    """十进制上限串转整数：逐位累加，任意长度按数学整数处理。"""
    value = 0
    for char in token:
        value = value * 10 + ord(char) - ord("0")
    return value


def _parse_limits(tokens, counts, defaults):
    """解析可选上限（个数须属于 counts，均须匹配 [1-9][0-9]*）。

    返回解析值加 defaults 中缺省项；个数不对或任一参数非法返回 None
    （调用方按 usage 处理）。
    """
    if len(tokens) not in counts:
        return None
    if any(_LIMIT_RE.fullmatch(token) is None for token in tokens):
        return None
    parsed = tuple(_limit_value(token) for token in tokens)
    return parsed + defaults[len(parsed):]


def _read_limited(handle, limit):
    """按至多 65536 字节分块读取；超过 limit 即停止并返回 None。

    额度未尽时单次至多请求剩余量，耗尽后只读 1 字节探测超限。
    """
    chunks = []
    total = 0
    while True:
        remaining = limit - total
        if remaining > 0:
            chunk = handle.read(min(_READ_CHUNK, remaining))
        else:
            chunk = handle.read(1)
        if not chunk:
            return b"".join(chunks)
        chunks.append(chunk)
        total += len(chunk)
        if total > limit:
            return None


RECORD_SCHEMA = 1
LOG_KEYS = ("schema", "config", "records", "sha256")
RECORD_KEYS = ("t", "version", "event", "applied", "output")
EVENT_KIND_BY_KEYS = {
    STP_EVENT_KEYS: "link",
    MEMBER_EVENT_KEYS: "member",
    SERVICE_EVENT_KEYS: "service",
    FRAME_KEYS_ACL: "frame",
    RELOAD_EVENT_KEYS: "reload",
    ROLLBACK_EVENT_KEYS: "rollback",
}
_HEX64_RE = re.compile(r"[0-9a-f]{64}\Z")


def _event_kind(event):
    if not isinstance(event, dict):
        raise InvalidInput("bad log event")
    kind = EVENT_KIND_BY_KEYS.get(frozenset(event))
    if kind is None:
        raise InvalidInput("bad log event")
    return kind


def _log_mode(config):
    """record/replay 按 config 形状选模式：loop-detect 或 port-security。"""
    if isinstance(config, dict) and frozenset(config) == LOOP_CONFIG_KEYS:
        return "loop"
    return "security"


def _run_loop_detect(config, events, observe, max_work=None):
    """record/replay 环路模式：校验 loop-detect 配置与事件并执行仿真。

    语义同 loop-detect 子命令；工作量预演（V*(L+1)*(事件数+1)）在
    loop_detect 内、正式仿真前无副作用完成，超限抛 LoopWorkLimit。
    返回 (loop-detect 结果 dict, observer 或 None)。
    """
    bridges, links, vlans = validate_loop_detect_config(config)
    link_ids = {link["id"] for link in links}
    stp_events = validate_stp_events(events, link_ids)
    observer = {} if observe else None
    result = loop_detect(
        links, vlans, stp_events, max_work, observer=observer
    )
    return result, observer


def _run_reload(config, events, observe, max_work=None):
    """reload/record/replay 共用：校验配置与事件并执行 port-security 仿真。

    事件允许 {t, rollback} 回滚事件（语义同 reload-rollback 子命令）。
    返回 (reload 结果 dict, observer 或 None)。全部校验与非法重载检测先于返回。
    max_work 非 None 时（record），全量语义校验后先按 reload 公式无副作用
    预演；首次超过即抛 ReloadWorkLimit，不正式仿真。
    """
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
    ) = validate_security_config(config)
    link_ids = {link["id"] for link in links}
    reload_events, final_config = validate_reload_events(
        events, ports, link_ids, lags, config, allow_rollback=True
    )
    if max_work is not None:
        # 与 reload 入口同一公式：独立链路副本与空状态，不改动既有数据
        reload_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            acl,
            qos,
            security,
            reload_events,
            max_work,
        )
    observer = {} if observe else None
    result = forward_security(
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
        reload_events,
        observer=observer,
    )
    result["config"] = _canonical(final_config)
    return result, observer


def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    loop_mode = _log_mode(config) == "loop"
    records = []
    # version 初值 0，取事件后值；安全模式每次 reload/rollback（无变化
    # 亦算）加 1，环路模式链路 up 实际改变（applied）才加 1
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if loop_mode:
            if observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        if record["output"] is not None and not isinstance(
            record["output"], dict
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    loop_mode = _log_mode(log["config"]) == "loop"
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if loop_mode:
            if observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        if _log_mode(config) == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (ReloadWorkLimit, LoopWorkLimit):
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path, max_events, max_log_bytes, max_output_bytes, max_replay_work
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        # records 上界在解析校验后、重放前判定
        if len(log["records"]) > max_events:
            _fail("event_limit")
            return 5
        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，
        # 不正式重放，LOG 保持不动
        if _log_mode(config) == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_replay_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_replay_work
            )
        _verify_records(log, events, observer["items"])
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (ReloadWorkLimit, LoopWorkLimit):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )

def validate_link_forward_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != LINK_FORWARD_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    # ports/age 与新式 forward 契约一致；每口删 up、增 rates/modes，
    # rates/modes 约束同 link-state 端口
    age = config["age"]
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    port_docs = config["ports"]
    if not isinstance(port_docs, list) or not port_docs:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    caps = {}
    fwd_ports = []
    for port in port_docs:
        if not isinstance(port, dict) or frozenset(port) != (
            PORT_KEYS_V2 - {"up"}
        ) | {"rates", "modes"}:
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        rates = _validate_link_state_rates(port["rates"])
        modes = _validate_link_state_modes(port["modes"])
        caps[name] = (rates, modes)
        # 其余字段约束同新式 forward 端口（补恒为 false 的 up）
        fwd_ports.append(
            {
                "name": name,
                "mode": port["mode"],
                "pvid": port["pvid"],
                "allowed": port["allowed"],
                "untagged": port["untagged"],
                "up": False,
            }
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    # 复用新式 forward 端口全量校验（mode/pvid/allowed/untagged）
    validate_forward_config_v2({"ports": fwd_ports, "age": age})
    return fwd_ports, caps, age, max_frame, delay


def validate_link_forward_events(events, fwd_ports):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in fwd_ports}
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == LINK_FORWARD_LINK_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            port = event["port"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            admin = event["admin"]
            peer = event["peer"]
            if not isinstance(admin, bool) or not isinstance(peer, bool):
                raise InvalidInput("bad admin/peer")
            rates = _validate_link_state_rates(event["rates"])
            modes = _validate_link_state_modes(event["modes"])
            result.append(("link", t, port, admin, peer, rates, modes))
        elif keys == LINK_FORWARD_FRAME_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            port = event["port"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            src = event["src"]
            dst = event["dst"]
            tag = event["vlan"]
            length = event["length"]
            fcs = event["fcs"]
            alignment = event["alignment"]
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if dst != BROADCAST_MAC and not valid_mac(dst):
                raise InvalidInput("bad dst")
            if tag is not None and not _valid_vlan_id(tag):
                raise InvalidInput("bad vlan")
            if not _is_int(length) or length < 0:
                raise InvalidInput("bad length")
            if not isinstance(fcs, bool):
                raise InvalidInput("bad fcs")
            if not isinstance(alignment, bool):
                raise InvalidInput("bad alignment")
            result.append(
                ("frame", t, port, src, dst, tag, length, fcs, alignment)
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result


def link_forward(fwd_ports, caps, age, max_frame, delay, events):
    by_name = {port["name"]: port for port in fwd_ports}
    # 协商状态：("down",)/("bad",)/("up", rate, mode)；初始皆 down
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)；仅 up 目标需协商
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        name: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for name in by_name
    }
    vlan_stats = {}
    for port in fwd_ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []

    def settle(t):
        # 完成截止 <= t 的协商，返回到期口名（保序同 link-state）
        due = [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]
        for name in due:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        return due

    def apply_link(t, port, admin, peer, rates, modes):
        settle(t)
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        # 变更前的有效态：在 wait（pending 未完成）即非 up
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            # 目标变化即进入 wait 并于 t+delay 完成
            pending[port] = (target[1], target[2], t + delay)
        else:
            # down/bad 立即生效
            pending.pop(port, None)
            committed[port] = target
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
            now_up = False
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
                now_up = True
            else:
                state, rate, mode = now[0], None, None
                now_up = False
        # 离开 up（up 转 wait/down/bad）即清该口 FDB；恢复 up 不恢复表项
        if before_up and not now_up:
            for key in [k for k, (p, _) in fdb.items() if p == port]:
                del fdb[key]
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )

    def is_up(name):
        # 有效 up：无未完成协商且 committed 为 up（wait 期间不转发）
        return name not in pending and committed[name][0] == "up"

    for item in events:
        t = item[1]
        # 逐项先完成截止 <= t 的协商（帧项无协商项，但到期口先转 up）
        settle(t)
        if item[0] == "link":
            _, t, port, admin, peer, rates, modes = item
            apply_link(t, port, admin, peer, rates, modes)
            continue
        (
            _,
            t,
            port_name,
            src,
            dst,
            tag,
            length,
            fcs,
            alignment,
        ) = item
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            continue
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # 拒绝帧丢弃且不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            continue
        vlan_stats[vlan]["rx"] += 1
        egress = []
        action = "drop"
        if is_up(port_name):  # 仅 up 口学习并作出口
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target_name = hit[0]
                if (
                    is_up(target_name)
                    and vlan in by_name[target_name]["allowed"]
                ):
                    egress = [target_name]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in fwd_ports
                    if vlan in port["allowed"]
                    and is_up(port["name"])
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append(
            {"t": t, "class": cls, "action": action, "ports": out_ports}
        )
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "rx": port_stats[name]["rx"],
                "tx": port_stats[name]["tx"],
                "drop": port_stats[name]["drop"],
                "good": port_stats[name]["good"],
                "runt": port_stats[name]["runt"],
                "giant": port_stats[name]["giant"],
                "alignment": port_stats[name]["alignment"],
                "bad_fcs": port_stats[name]["bad_fcs"],
            }
            for name in by_name
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def link_forward_work(fwd_ports, events, limit):
    """link-forward 的工作量预演：只计端口数与此前帧数，无副作用。

    P 为端口数、F 为此前帧数，W 初值 P；每事件处理前加 F+2P+1（协商项与
    帧项均计费），帧事件随后令 F 加 1。累计等于上限合法，首次超过即抛
    LinkForwardWorkLimit，不访问后续事件。
    """
    frames_seen = 0
    width = 2 * len(fwd_ports) + 1
    work = len(fwd_ports)  # W 初值 P
    if work > limit:
        raise LinkForwardWorkLimit()
    for item in events:
        work += frames_seen + width
        if work > limit:
            raise LinkForwardWorkLimit()
        if item[0] == "frame":
            frames_seen += 1


